_name":"escape_route_products","rls_enabled":true},{"table_name":"escape_routes","rls_enabled":true},{"table_name":"products","rls_enabled":true}],"public_read_policies":[{"cmd":"SELECT","qual":"((EXISTS ( SELECT 1\n   FROM software_discovery.escape_routes er\n  WHERE ((er.id = escape_route_products.escape_route_id) AND (er.status = 'published'::text) AND (er.editorially_approved = true)))) AND (EXISTS ( SELECT 1\n   FROM software_discovery.products p\n  WHERE ((p.id = escape_route_products.product_id) AND (p.status = 'published'::text)))))","roles":["anon","authenticated"],"tablename":"escape_route_products","permissive":"PERMISSIVE","policyname":"public_escape_route_products_read","schemaname":"software_discovery","with_check":null},{"cmd":"SELECT","qual":"((status = 'published'::text) AND (editorially_approved = true))","roles":["anon","authenticated"],"tablename":"escape_routes","permissive":"PERMISSIVE","policyname":"approved_escape_routes_public_read","schemaname":"software_discovery","with_check":null},{"cmd":"SELECT","qual":"(status = 'published'::text)","roles":["anon","authenticated"],"tablename":"products","permissive":"PERMISSIVE","policyname":"published_products_public_read","schemaname":"software_discovery","with_check":null}]}}$payload$::jsonb; op jsonb; expected jsonb; actual jsonb;
BEGIN
 PERFORM set_config('lock_timeout','10s',true);
 PERFORM set_config('TimeZone','UTC',true);
 PERFORM pg_advisory_xact_lock(7232003);
 LOCK TABLE software_discovery.products,software_discovery.product_attributes,software_discovery.product_anchors,software_discovery.product_problems,software_discovery.product_audiences,software_discovery.product_attribute_evidence,software_discovery.product_anchor_evidence,software_discovery.product_problem_evidence,software_discovery.product_audience_evidence,software_discovery.claim_evidence,software_discovery.evidence_sources,software_discovery.attributes,software_discovery.anchors,software_discovery.problems,software_discovery.audiences,software_discovery.escape_routes,software_discovery.escape_route_products IN SHARE ROW EXCLUSIVE MODE;
 IF coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.products WHERE status='published'),'[]'::jsonb)<>data->'snapshot'->'published_products' OR coalesce((SELECT jsonb_agg(slug ORDER BY slug) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved),'[]'::jsonb)<>data->'snapshot'->'approved_published_routes' THEN RAISE EXCEPTION 'PR5.70 publication state drift or repeated apply; fresh preflight required'; END IF;
 IF NOT has_function_privilege('anon','software_discovery.product_discovery_page(text)','EXECUTE') OR has_table_privilege('anon','software_discovery.claim_evidence','SELECT') THEN RAISE EXCEPTION 'PR5.70 private evidence boundary drift'; END IF;
 IF (SELECT coalesce(jsonb_agg(jsonb_build_object('table_name',c.relname,'rls_enabled',c.relrowsecurity) ORDER BY c.relname),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='software_discovery' AND c.relname IN ('products','escape_routes','escape_route_products'))<>data->'snapshot'->'public_read_rls' OR (SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname),'[]'::jsonb) FROM pg_policies p WHERE schemaname='software_discovery' AND tablename IN ('products','escape_routes','escape_route_products'))<>data->'snapshot'->'public_read_policies' THEN RAISE EXCEPTION 'PR5.70 public read policy drift'; END IF;
 FOR op IN SELECT value FROM jsonb_array_elements(data->'guards') LOOP
  EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(jsonb_populate_record(NULL::software_discovery.%I,r))-''created_at''-''updated_at'' j FROM jsonb_array_elements($1) r) x',op->>'table') INTO expected USING op->'rows';
  EXECUTE format('SELECT coalesce(jsonb_agg(j ORDER BY j::text),''[]''::jsonb) FROM (SELECT to_jsonb(t)-''created_at''-''updated_at'' j FROM software_discovery.%I t WHERE %s) x',op->>'table',op->>'where') INTO actual;
  IF expected<>actual THEN RAISE EXCEPTION 'PR5.70 stored baseline drift: %',op->>'table'; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM software_discovery.products WHERE id IN ('f6150c8b-5485-4f65-b769-a27b6f50af66','964e1139-e9ce-4b9a-93eb-e4cf43ad2a02','8fff305e-bbbf-4b61-80c7-0f2dcffc68ad') AND software_discovery.product_discovery_page(slug) IS NOT NULL) THEN RAISE EXCEPTION 'PR5.70 draft public visibility drift'; END IF;
 UPDATE software_discovery.products SET status='published' WHERE id IN ('f6150c8b-5485-4f65-b769-a27b6f50af66','964e1139-e9ce-4b9a-93eb-e4cf43ad2a02','8fff305e-bbbf-4b61-80c7-0f2dcffc68ad');
 UPDATE software_discovery.escape_routes SET status='published',editorially_approved=true WHERE id='e0170d70-5f76-4d56-b541-858ec84a0f19';
 IF (SELECT count(*) FROM software_discovery.products WHERE status='published')<>21 OR (SELECT count(*) FROM software_discovery.escape_routes WHERE status='published' AND editorially_approved)<>9 THEN RAISE EXCEPTION 'PR5.70 post-publication count mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM software_discovery.products p WHERE p.id IN ('f6150c8b-5485-4f65-b769-a27b6f50af66','964e1139-e9ce-4b9a-93eb-e4cf43ad2a02','8fff305e-bbbf-4b61-80c7-0f2dcffc68ad') AND (software_discovery.product_discovery_page(p.slug) IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(software_discovery.product_discovery_page(p.slug)->'anchors') a WHERE a->>'slug'='grammarly' AND a->>'scope'='personal-english-passive-construction-review' AND a->>'verificationStatus'='verified' AND length(a->>'description')>0 AND jsonb_array_length(a->'sources')>0) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(software_discovery.product_discovery_page(p.slug)->'attributes') a WHERE a->>'slug'='no-subscription' AND a->'value'='true'::jsonb AND a->>'verificationStatus'='verified' AND jsonb_array_length(a->'sources')>0))) THEN RAISE EXCEPTION 'PR5.70 public qualified projection missing'; END IF;
 -- Apply persists only after owner approval.
EXCEPTION WHEN SQLSTATE 'ZSR01' THEN RAISE NOTICE 'Writing publication rehearsal rolled back; no changes persisted';
END $writing_publish$;
